-- Seed: Off Plan International communities (carga unica desde CSV de Webflow)
-- Ejecutar despues de la migracion 008_communities.sql
-- Nota: developer_id se deja NULL y NO se incluye en el DO UPDATE a proposito,
-- para no pisar asignaciones manuales hechas desde el panel de administracion.

ON CONFLICT (slug) DO UPDATE SET
  country = EXCLUDED.country,
  city = EXCLUDED.city,
  location = EXCLUDED.location,
  average_price_range = EXCLUDED.average_price_range,
  highlight_image = EXCLUDED.highlight_image,
  images = EXCLUDED.images,
  tags = EXCLUDED.tags,
  google_map_url = EXCLUDED.google_map_url,
  is_active = EXCLUDED.is_active;

ON CONFLICT (community_id, locale) DO UPDATE SET
  name = EXCLUDED.name,
  short_description = EXCLUDED.short_description,
  description = EXCLUDED.description;
